module old021::tasks;
fn answer()->i64 !{task}{return with_tasks(2,fn(s:task_scope)->i64 !{task}{let x:task<i64>=task_spawn(s,fn()->i64{return 42;});return task_wait(x);});}
fn main()->unit !{task,io}{print(answer());}
test fn retained_answer()->unit !{task}{assert(answer()==42);}

